#include <cuda_runtime.h>
#include "native_kernels.inc"
#include <vector>
#include <string>
#include <cstring>
#include <chrono>
#define CK(x) do{cudaError_t e=(x);if(e!=cudaSuccess){fprintf(stderr,"%s:%d %s\n",__FILE__,__LINE__,cudaGetErrorString(e));exit(2);}}while(0)
std::vector<double>rd(const char*n){FILE*f=fopen(n,"rb");fseek(f,0,SEEK_END);size_t z=ftell(f)/8;rewind(f);std::vector<double>a(z);if(fread(a.data(),8,z,f)!=z)abort();fclose(f);return a;}
const int SZ=40960,LEAD=20,TAIL=8,LEN=SZ+LEAD+TAIL;
const int regions[7][6]={{0,24,0,24,0,8},{0,24,0,8,8,16},{0,8,8,16,8,16},{8,16,8,16,8,16},{16,24,8,16,8,16},{0,24,16,24,8,16},{0,24,0,24,16,24}};
struct Case{int ns;std::vector<float>source;std::vector<std::vector<float>>hs;float*d[5];};
#define KARGS 24LL,24LL,24LL,40,32,32,b[0],b[1],b[2],b[3],b[4],b[5],4LL,4LL,4LL,hd[0],hd[1],hd[2],c0,c[0],c[3],c[6],c[9],c[1],c[4],c[7],c[10],c[2],c[5],c[8],c[11],u,v,vp,phi,eta
void launch(Case&a,float c0,const float*c,const float*hd){float*u=a.d[0]+LEAD,*v=a.d[1]+LEAD,*phi=a.d[2]+LEAD,*vp=a.d[3]+LEAD,*eta=a.d[4]+LEAD;for(int step=1;step<=a.ns;step++){for(int reg=0;reg<7;reg++){auto*b=regions[reg];dim3 blocks((b[5]-b[4])/8,(b[3]-b[2])/8,(b[1]-b[0])/8);if(reg==3)target_inner_3d_kernel<<<blocks,dim3(8,8,8)>>>(KARGS);else target_pml_3d_kernel<<<blocks,dim3(8,8,8)>>>(KARGS);CK(cudaGetLastError());}kernel_add_source_kernel<<<1,1>>>(v,((12+4)*32+12+4)*32+12+4,a.source[step]);CK(cudaGetLastError());auto*t=u;u=v;v=t;}}
int main(){auto pre=rd(FIXTURE),gold=rd(ORACLE);if(pre[0]!=3||pre[1]!=24)abort();float c0=pre[7],c[12],hd[3];for(int j=0;j<12;j++)c[j]=pre[8+j];for(int j=0;j<3;j++)hd[j]=pre[20+j];size_t pos=23;std::vector<Case>cs;for(int ci=0;ci<3;ci++){Case a;a.ns=pre[pos++];for(int j=0;j<=a.ns;j++)a.source.push_back(pre[pos++]);for(int f=0;f<5;f++){std::vector<float>h(LEN,-12345);for(int j=0;j<SZ;j++)h[j+LEAD]=pre[pos++];a.hs.push_back(h);CK(cudaMalloc(&a.d[f],LEN*4));CK(cudaMemcpy(a.d[f],h.data(),LEN*4,cudaMemcpyHostToDevice));}cs.push_back(a);}if(pos!=pre.size())abort();for(auto&a:cs){launch(a,c0,c,hd);CK(cudaDeviceSynchronize());}
for(int trial=1;trial<=5;trial++){auto art=pre;size_t go=0;bool ok=true;double ma=0,mr=0,total=0;std::vector<double>times;
for(int ci=0;ci<3;ci++){auto&a=cs[ci];std::vector<std::vector<float>>before;for(int f=0;f<5;f++){CK(cudaMemcpy(a.d[f],a.hs[f].data(),LEN*4,cudaMemcpyHostToDevice));std::vector<float>v(LEN);CK(cudaMemcpy(v.data(),a.d[f],LEN*4,cudaMemcpyDeviceToHost));ok&=memcmp(v.data(),a.hs[f].data(),LEN*4)==0;before.push_back(v);}CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();launch(a,c0,c,hd);CK(cudaDeviceSynchronize());double dt=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();times.push_back(dt);total+=dt;std::vector<std::vector<float>>after;for(int f=0;f<5;f++){int owner=f<2&&(a.ns&1)?1-f:f;std::vector<float>v(LEN);CK(cudaMemcpy(v.data(),a.d[owner],LEN*4,cudaMemcpyDeviceToHost));after.push_back(v);}
for(int f=0;f<5;f++)for(int j=0;j<LEN;j++){double x=after[f][j],r=gold[go++],e=fabs(x-r);bool exact=ci==2||j<LEAD||j>=SZ+LEAD||f>=3;if(!exact){int off=j-LEAD,k=off%32-4,y=(off/32)%32-4,i=off/1024-4;bool active=i>=0&&i<24&&y>=0&&y<24&&k>=0&&k<24;bool pml=active&&!(i>=8&&i<16&&y>=8&&y<16&&k>=8&&k<16);exact=f==2?!pml:!active;}double at=f==2?1e-10:2e-6;ok&=std::isfinite(x)&&(exact?x==r:e<=at+2e-5*fabs(r));ma=fmax(ma,e);mr=fmax(mr,e/(fabs(r)+1e-300));art.push_back(x);}for(auto&v:before)for(float x:v){ok&=x==gold[go++];art.push_back(x);}}
if(go!=gold.size())abort();std::string path=std::string(getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".")+"/output_trial"+std::to_string(trial)+".bin";FILE*f=fopen(path.c_str(),"wb");fwrite(art.data(),8,art.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":%.17g,\"timing_region\":\"sum3_complete_seven_region_wave_PML_step_components\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"},\"path_times_seconds\":[",trial,total,ok?"true":"false",go,ma,mr,path.c_str(),art.size());for(size_t i=0;i<times.size();i++)printf("%s%.17g",i?",":"",times[i]);printf("]}\n");}}
